import React, { useEffect, useState } from "react";
import axios from "axios";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
import "../styles/AdminAcademics.css";

export default function AdminManageAcademics() {
  const [formData, setFormData] = useState({
    curriculum: "",
    subjects: "",
    faculty: "",
    examination: "",
  });

  useEffect(() => {
    axios.get("http://localhost:5000/api/academics")
      .then(res => res.data && setFormData(res.data))
      .catch(err => console.error(err));
  }, []);

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleSave = async () => {
    try {
      const token = localStorage.getItem("token");
      await axios.put(
        "http://localhost:5000/api/academics",
        formData,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      alert("Academics content updated successfully!");
    } catch (err) {
      alert("Error updating academics content.");
      console.error(err);
    }
  };

  return (
    <div className="admin-academics-container">
      <h2>Manage Academics Page</h2>

      {["curriculum", "subjects", "faculty", "examination"].map((field) => (
        <div key={field} className="editor-section">
          <h3>{field.charAt(0).toUpperCase() + field.slice(1)}</h3>
          <ReactQuill
            theme="snow"
            value={formData[field]}
            onChange={(value) => handleChange(field, value)}
            className="editor-box"
          />
        </div>
      ))}

      <button onClick={handleSave} className="save-btn">Save Changes</button>
    </div>
  );
}
